                                "Recorded_Future_RiskLists_and_SCF_Download": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Foreach"
                        },
                        "For_each_2": {
                            "actions": {
                                "Parse_JSON_2": {
                                    "inputs": {
                                        "content": "@items('For_each_2')",
                                        "schema": {
                                            "properties": {
                                                "EvidenceDetails": {
                                                    "properties": {
                                                        "EvidenceDetails": {
                                                            "items": {
                                                                "properties": {
