                                                                    "Criticality"
                                                                ],
                                                                "type": "object"
                                                            },
                                                            "type": "array"
                                                        }
                                                    },
                                                    "type": "object"
                                                },
                                                "Name": {
                                                    "type": "string"
                                                },
                                                "Risk": {
                                                    "type": "integer"
                                                },
                                                "riskString": {
                                                    "type": "string"
                                                }
                                            },
                                            "type": "object"
                                        }
                                    },
                                    "runAfter": {},
                                    "type": "ParseJson"
                                },
                                "RecordedFuture_Generic_Detection_ImportToSentinel_2": {
                                    "inputs": {
                                        "batchName": "[parameters('BatchName')]",
                                        "content": {
                                            "action": "alert",
                                            "additionalInformation": "@{body('Parse_JSON_2')?['EvidenceDetails']}",
