                                }
                            },
                            "foreach": "@body('Recorded_Future_RiskLists_and_SCF_Download_2')",
                            "runAfter": {
                                "Recorded_Future_RiskLists_and_SCF_Download_2": [
                                    "Succeeded"
                                ]
                            },
                            "type": "Foreach"
                        },
                        "Recorded_Future_RiskLists_and_SCF_Download": {
                            "inputs": {
