{
    "$schema": "https://schema.management.azure.com/schemas/2015-01-01/deploymentTemplate.json#",
    "contentVersion": "1.0.0.0",
    "metadata": {
		"comment": "This playbook leverages Recorded Future API and automatically imports the Command and Control IPs and Weaponized Domains Security Control Feeds, as Threat Intelligence Indicators, for prevention purposes in Microsoft Defender for Endpoint",
		"author": "Glenn Wong & Adrian Porcescu, Recorded Future"
	},
    "parameters": {
        "PlaybookName": {
            "defaultValue": "RecordedFuture-ImportToDefenderEndpoint",
            "type": "string"
        },
        "UserName": {
            "defaultValue": "<username>@<domain>",
            "type": "string"
        }
    },
    "variables": {
		"GraphSecurityConnectionName": "[concat('microsoftgraphsecurity-', parameters('PlaybookName'))]"
	},
    "resources": [
        {
			"type": "Microsoft.Logic/workflows",
			"apiVersion": "2016-06-01",
			"name": "[parameters('PlaybookName')]",
			"location": "[resourceGroup().location]",
			"dependsOn": [
				"[resourceId('Microsoft.Web/connections', variables('GraphSecurityConnectionName'))]"
			],
			"properties": {
				"definition": {
                    "$schema": "https://schema.management.azure.com/providers/Microsoft.Logic/schemas/2016-06-01/workflowdefinition.json#",
                    "actions": {
                        "Select": {
                            "inputs": {
                                "from": "@triggerBody()['items']",
                                "select": "@item()['content']"
                            },
                            "runAfter": {},
                            "type": "Select"
                        },
                        "Submit_multiple_tiIndicators": {
                            "inputs": {
                                "body": {
                                    "value": "@body('Select')"
                                },
                                "host": {
                                    "connection": {
                                        "name": "@parameters('$connections')['microsoftgraphsecurity']['connectionId']"
                                    }
                                },
                                "method": "post",
                                "path": "/beta/security/tiIndicators/submitTiIndicators"
                            },
                            "runAfter": {
                                "Select": [
                                    "Succeeded"
                                ]
                            },
                            "type": "ApiConnection"
                        }
                    },
                    "contentVersion": "1.0.0.0",
                    "outputs": {},
                    "parameters": {
                        "$connections": {
                            "defaultValue": {},
                            "type": "Object"
                        }
                    },
                    "triggers": {
                        "Batch_messages": {
                            "inputs": {
                                "configurations": {
                                    "BatchImportToMGS": {
                                        "releaseCriteria": {
                                            "messageCount": 100,
                                            "recurrence": {
                                                "frequency": "Minute",
                                                "interval": 5
                                            }
                                        }
                                    }
                                },
                                "mode": "Inline"
                            },
                            "type": "Batch"
                        }
                    }
                },
				"parameters": {
					"$connections": {
						"value": {
							"microsoftgraphsecurity": {
								"id": "[concat('/subscriptions/',subscription().subscriptionId,'/providers/Microsoft.Web/locations/',resourceGroup().location,'/managedApis/microsoftgraphsecurity')]",
								"connectionId": "[resourceId('Microsoft.Web/connections', variables('GraphSecurityConnectionName'))]",
								"connectionName": "[variables('GraphSecurityConnectionName')]"
							}
						}
					}
				}
			}
		},
        {
			"type": "Microsoft.Web/connections",
			"apiVersion": "2016-06-01",
			"location": "[resourceGroup().location]",
			"name": "[variables('GraphSecurityConnectionName')]",
			"properties": {
                "displayName": "[parameters('UserName')]",
                "customParameterValues": {},
				"api": {
					"id": "[concat('/subscriptions/',subscription().subscriptionId,'/providers/Microsoft.Web/locations/',resourceGroup().location,'/managedApis/microsoftgraphsecurity')]"
				}
			}
		}
    ]
}

