                      "statusCode": "@outputs('Scope_output')['statusCode']"
                    },
                    "operationOptions": "Asynchronous"
                  },
                  "Scope_output": {
                    "runAfter": {},
                    "type": "Compose",
                    "inputs": "@outputs('Filter_array')?['body']?[0]?['outputs']"
                  }
                }
              },
              "expression": {
                "and": [
