                                        "Get_username": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "Compose"
                                },                                
                                "Get_alertLink": {
                                    "inputs": {
                                        "from": "@triggerBody()?['ExtendedLinks']",
                                        "where": "@contains(item()['Label'], 'alert')"
                                    },
                                    "runAfter": {
                                        "Compose_UPN": [
                                            "Succeeded"
                                        ]
                                    },
                                    "type": "Query"
                                },
                                "Extract_alertId": {
                                    "inputs": "@last(split(body('Get_alertLink')[0]['Href'], '/'))",
